{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C01","C02","C06","C14","C15","C18"],
  "contradictory_card_ids": ["C28"],
  "prediction_basis_card_ids": ["C01","C02","C06","C14","C15","C18"],
  "claims": [
    {
      "claim": "Esaxerenone, the closest structural context sharing the methyl-amide-aryl and CF3/OCF3-bearing biaryl motif, had absolute oral bioavailability of 89.0% fasting and 90.8% postprandial in healthy subjects, well above the 20% threshold.",
      "card_ids": ["C01","C02","C10","C11","C12","C20","C26"]
    },
    {
      "claim": "Nilotinib, a lipophilic CF3-containing amide with precipitation-limited absorption, had absolute oral bioavailability of about 31% under fasted conditions, still above the 20% threshold.",
      "card_ids": ["C06","C22","C34"]
    },
    {
      "claim": "Elinzanetant, a lipophilic CF3-containing amide with a morpholine-type amine, had oral bioavailability of 36.7% and is described as orally bioavailable.",
      "card_ids": ["C15","C17","C23"]
    },
    {
      "claim": "Glasdegib and OTX015, other amide/heteroaryl oral drugs, had F of 77% and good oral bioavailability, respectively.",
      "card_ids": ["C14","C19","C18","C24","C31"]
    },
    {
      "claim": "The L3 oral AUC/Cmax records are for unrelated reference molecules (tedizolid, nelfinavir, meloxicam, and M04) and do not provide query-specific F evidence; tedizolid's oral/IV AUC ratio (~86%) is supportive for tedizolid only.",
      "card_ids": ["C46","C37","C44"]
    },
    {
      "claim": "The only sub-20% value in the evidence set is isradipine's 16% non-cirrhotic comparator, but isradipine is structurally dissimilar and the context's gold outcome is cirrhotic 37%; this low-transferability record does not affirm F<20% for the query chemotype.",
      "card_ids": ["C28","C04","C09","C29"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C35","C36","C37","C38","C39","C40","C41","C42","C43","C44","C45","C46"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "No query-specific oral AUC/Cmax record is available; all L3 exposure records are for tedizolid, nelfinavir, meloxicam, and M04, none structurally close to the query.",
    "No experimental solubility, permeability, or first-pass data are available for the query; the low prior is physicochemical only.",
    "Condition matching is imperfect: the query has no reported external condition, while many contexts are fasted, fed, or cirrhosis-specific.",
    "The query's OCF3 and 2,6-dimethylmorpholine-pyridine combination is not exactly covered by any card; closest analogs differ in polar substituents and formulation."
  ],
  "decision_summary": "Prediction remains high: all transferable numeric gold records for structurally relevant amide/heteroaryl contexts are >=31%, with closest analogs esaxerenone (89-91%) and nilotinib (31%) supporting F>=20%; L3 oral exposure records are not query-specific and do not alter the decision; the low physicochemical prior and the low-transferability isradipine 16% comparator do not provide affirmative evidence of F<20% for this chemotype. Confidence is moderate because no direct query measurement is available."
}

